// Toy digest stands in for sha512 (QuickJS is deterministic; no crypto needed).
function digest(bytes) {
  let h = 5381;
  for (let i = 0; i < bytes.length; i++) h = ((h << 5) + h + bytes.charCodeAt(i)) & 0xffffffff;
  return 'sha-' + (h >>> 0).toString(16);
}
// Lockfile: name -> { version, integrity } recorded at lock time.
const lockfile = {
  'left-pad':   { version: '1.3.0', integrity: digest('left-pad@1.3.0::clean-bytes') },
  'cross-env':  { version: '7.0.3', integrity: digest('cross-env@7.0.3::clean-bytes') },
  'ua-parser':  { version: '0.7.30', integrity: digest('ua-parser@0.7.30::clean-bytes') }
};
// What the registry actually served this install (ua-parser was republished
// under the SAME version with tampered bytes — the integrity hash won't match).
const downloaded = {
  'left-pad':   { version: '1.3.0', bytes: 'left-pad@1.3.0::clean-bytes' },
  'cross-env':  { version: '7.0.3', bytes: 'cross-env@7.0.3::clean-bytes' },
  'ua-parser':  { version: '0.7.30', bytes: 'ua-parser@0.7.30::MINER-PAYLOAD' }
};

function verify(name) {
  const locked = lockfile[name];
  const got = downloaded[name];
  if (locked.version !== got.version) return name + ': FAIL version ' + got.version + ' != ' + locked.version;
  return digest(got.bytes) === locked.integrity
    ? name + ': OK'
    : name + ': FAIL integrity';
}

const names = ['left-pad', 'cross-env', 'ua-parser'];
const results = names.map(verify);
const failed = results.filter(r => r.indexOf('FAIL') !== -1).length;
results.forEach(r => console.log(r));
console.log(failed === 0 ? 'npm ci: install OK' : 'npm ci: aborted, ' + failed + ' package(s) failed integrity');
